"use client";
import { useState } from "react";
import { parseDimensions } from "@/lib/inventory-product-facts";
const presets = Array.from({ length: 2000 }, (_, index) => String((index + 1) / 10));
export function InventoryDimensions({ value, onChange }: { value?: string; onChange: (value: string) => void }) {
 const [custom, setCustom] = useState<number[]>([]);
 const parsed = parseDimensions(value), sizes = parsed ? [parsed.lengthMm, parsed.widthMm, parsed.breadthMm] : (value || "").split(/\s*x\s*/i).concat(["", "", ""]).slice(0, 3).map((v) => /^\d+(\.\d+)?$/.test(v) ? v : "");
 return <div className="space-y-2"><div className="grid grid-cols-3 gap-3">{["Length", "Width", "Breadth"].map((label, index) => <label key={label} className="text-sm">{label} (mm)<select aria-label={`${label} (mm)`} className="mt-1 h-10 w-full rounded-md border bg-background px-2" value={custom.includes(index) ? "custom" : sizes[index]} onChange={(event) => { if (event.target.value === "custom") { setCustom((previous) => [...previous, index]); return; } const next = [...sizes]; next[index] = event.target.value; onChange(next.some(Boolean) ? next.slice(0, next[2] ? 3 : 2).join(" x ") : ""); }}><option value="">Select</option>{sizes[index] && !presets.includes(sizes[index]) && <option value={sizes[index]}>{sizes[index]} (saved)</option>}{presets.map((size) => <option key={size} value={size}>{size}</option>)}<option value="custom">Exact / other size…</option></select>{custom.includes(index) && <input aria-label={`${label} exact measurement`} className="mt-1 h-10 w-full rounded-md border bg-background px-2" type="number" min="0.001" step="any" value={sizes[index]} onChange={(event) => { const next = [...sizes]; next[index] = event.target.value; onChange(next.some(Boolean) ? next.slice(0, next[2] ? 3 : 2).join(" x ") : ""); }}/>}</label>)}</div><p className="text-xs text-muted-foreground">Length × width × breadth. 0.1–200 mm in 0.1 mm steps; existing precise sizes are retained.</p>{value && !parsed && <p className="text-xs text-amber-600">{value.includes(" x  x ") || / x $|^ x /.test(value) ? "Select all three measurements." : `Previous dimensions: ${value}. Review the three measurements before changing them.`}</p>}</div>;
}
